// Service worker for /book/ only (generated by book-drafts/build.py, through guide-ui/build_integration.py).
// Network first (content stays fresh), cache as offline fallback. The whole book is precached.
// - Installation fetches every CORE address from the server, not from the HTTP cache, and fails as a whole when one
//   is missing: the new worker then never activates and the previous offline copy stays in use.
// - The precached files are never overwritten while browsing, so offline the pages and their versioned assets (?v=)
//   always come from the same build. Other same-origin files the pages load (images, /external-links.js) are added.
// - Offline, a request is matched with its query string; only a page address falls back to the same page without it.
// - On activation it keeps the added files of the former copies, then deletes only the former caches of this book
//   (proof-book-*), never another cache of the origin.
// - The source archive (/book/source/) is left to the browser: never precached, never stored, online only.
const CACHE = 'proof-book-cf41e577';
const CORE = [
  '/book/',
  '/book/ai/',
  '/book/autonomy/',
  '/book/big-tech/',
  '/book/bitcoin-privacy/',
  '/book/browser/',
  '/book/checklist/',
  '/book/email/',
  '/book/en/',
  '/book/en/ai/',
  '/book/en/autonomy/',
  '/book/en/big-tech/',
  '/book/en/bitcoin-privacy/',
  '/book/en/browser/',
  '/book/en/checklist/',
  '/book/en/email/',
  '/book/en/first-wallet/',
  '/book/en/glossary/',
  '/book/en/hardware-wallet/',
  '/book/en/introduction/',
  '/book/en/keys/',
  '/book/en/legal/',
  '/book/en/lightning-and-euros/',
  '/book/en/messages/',
  '/book/en/network/',
  '/book/en/node/',
  '/book/en/nostr/',
  '/book/en/passwords/',
  '/book/en/phone/',
  '/book/en/privacy/',
  '/book/en/savings/',
  '/book/en/seed/',
  '/book/en/self-hosting/',
  '/book/en/start/',
  '/book/en/work/',
  '/book/first-wallet/',
  '/book/glossary/',
  '/book/guide-assets/config.js?v=3a5431c63656',
  '/book/guide-assets/fonts/jetbrainsmono-latin-ext.woff2?v=7db7affbce1f',
  '/book/guide-assets/fonts/jetbrainsmono-latin.woff2?v=1e06740a02a4',
  '/book/guide-assets/fonts/righteous-latin-ext.woff2?v=6373d7c7c233',
  '/book/guide-assets/fonts/righteous-latin.woff2?v=17bb3e21ead2',
  '/book/guide-assets/guide.css?v=b1a0514801f5',
  '/book/guide-assets/guide.js?v=f361d2b9248c',
  '/book/guide-assets/legal/LICENSE-CONTENT.txt?v=28a9529c7d0b',
  '/book/guide-assets/legal/LICENSE.txt?v=0d96a4ff68ad',
  '/book/guide-assets/legal/NOTICE.txt?v=07b9d77860aa',
  '/book/guide-assets/legal/OFL-JetBrainsMono.txt?v=b2fe5e898759',
  '/book/guide-assets/legal/OFL-Righteous.txt?v=1c5bc055869d',
  '/book/guide-assets/search-index-lt.js?v=8c9a6da0fbff',
  '/book/guide-assets/search-index.js?v=e6afda0bb20e',
  '/book/guide-assets/site-data-lt.js?v=66fbe9147120',
  '/book/guide-assets/site-data.js?v=ceca24ecd938',
  '/book/hardware-wallet/',
  '/book/introduction/',
  '/book/keys/',
  '/book/legal/',
  '/book/lightning-and-euros/',
  '/book/messages/',
  '/book/network/',
  '/book/node/',
  '/book/nostr/',
  '/book/passwords/',
  '/book/phone/',
  '/book/privacy/',
  '/book/savings/',
  '/book/seed/',
  '/book/self-hosting/',
  '/book/start/',
  '/book/work/',
  '/favicon.svg'
];
const CORE_PATHS = new Set(CORE.map((u) => new URL(u, self.location.origin).pathname));
const precached = (url) => CORE_PATHS.has(new URL(url).pathname);
const BYPASS = '/book/source/';

self.addEventListener('install', (e) => {
  e.waitUntil(
    caches.open(CACHE)
      .then((c) => c.addAll(CORE.map((u) => new Request(u, { cache: 'reload' }))))
      .then(() => self.skipWaiting())
  );
});

// Copies the added files of a former cache that this one lacks (never its CORE files), then deletes it.
function carryOver(cache, name) {
  return caches.open(name)
    .then((old) => old.keys().then((reqs) => Promise.all(reqs.filter((r) => !precached(r.url)).map((r) =>
      cache.match(r).then((has) => has || old.match(r).then((res) => res && cache.put(r, res)))))))
    .catch(() => { /* quota: the added files are fetched again online */ })
    .then(() => caches.delete(name));
}

self.addEventListener('activate', (e) => {
  e.waitUntil(
    caches.keys()
      .then((keys) => keys.filter((k) => k.indexOf('proof-book-') === 0 && k !== CACHE).reverse())
      .then((former) => caches.open(CACHE).then((cache) =>
        former.reduce((done, k) => done.then(() => carryOver(cache, k)), Promise.resolve())))
      .then(() => self.clients.claim())
  );
});

function offline(req) {
  return caches.open(CACHE)
    .then((c) => c.match(req, { ignoreVary: true })
      .then((hit) => hit || (req.mode === 'navigate' ? c.match(req, { ignoreSearch: true, ignoreVary: true }) : undefined)))
    .then((hit) => hit || Response.error());
}

self.addEventListener('fetch', (e) => {
  const req = e.request;
  const url = new URL(req.url);
  if (req.method !== 'GET' || url.origin !== self.location.origin || url.pathname.indexOf(BYPASS) === 0) return;
  e.respondWith(
    fetch(req)
      .then((res) => {
        if (res.ok && res.type === 'basic' && !precached(req.url)) {
          const copy = res.clone();
          e.waitUntil(caches.open(CACHE).then((c) => c.put(req, copy)).catch(() => { /* partial or too large */ }));
        }
        return res;
      })
      .catch(() => offline(req))
  );
});

// A page asks the active worker which complete copy it can serve. Never infer readiness from another cache.
self.addEventListener('message', (e) => {
  if (!e.data || e.data.type !== 'PROOF_OFFLINE_STATUS' || !e.ports[0]) return;
  e.waitUntil(caches.open(CACHE).then((c) => Promise.all(CORE.map((u) => c.match(u))))
    .then((hits) => e.ports[0].postMessage({ cache: CACHE, ready: hits.every(Boolean) }))
    .catch(() => e.ports[0].postMessage({ ready: false })));
});
